using System.Text;
using System.Text.Json;

internal sealed record LibraryDocumentVersion(string Id,int Version,LibraryFolderLink Association,SimLinkedSource Source,string[] Purposes,string Use,string Number,string Revision,string Status,string? EvidenceHash,LibraryActor SavedBy,[property: System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] string? Origin=null);
internal sealed record LibraryDocumentsRecord(string SourceKeyRaw,string DrawingRevision,string BomRevision,int Revision,LibraryDocumentVersion[] History);
internal sealed record LibraryDocumentCommand(string Key,string ExpectedToken,string FolderToken,string RelativePath,string SourceToken,string[] Purposes,string Use,string Number,string Revision,string Status,string? Origin=null);
internal sealed partial class SimLibraryBomStore
{
 private string DocumentsPath(string key,string drawing,string bom)=>Path.Combine(root,"documents",Hash(JsonSerializer.SerializeToUtf8Bytes(new[]{key,drawing,bom}))+".json");
 private static string DocumentsToken(LibraryDocumentsRecord record)=>Hash(JsonSerializer.SerializeToUtf8Bytes(record,Json));
 private async Task<LibraryDocumentsRecord> ReadDocuments(string key,string drawing,string bom){var path=DocumentsPath(key,drawing,bom);if(!File.Exists(path))return new(key,drawing,bom,0,[]);var r=JsonSerializer.Deserialize<LibraryDocumentsRecord>(await File.ReadAllTextAsync(path),Json)!;Require(r.SourceKeyRaw==key&&r.DrawingRevision==drawing&&r.BomRevision==bom,"Document context verification failed.");return r;}
 private async Task<LibraryFolderLink> DocumentLink(string key,string token){var f=await ReadFolder(key);Require(f.Current is not null,"Link an Assembly Folder from the assembly workspace first.");Require(FolderToken(f)==token,"The folder link changed. Reopen this workspace.");var c=await FolderContext(key);Require(f.Current!.DrawingRevision==c.Drawing&&f.Current.BomRevision==c.Bom,"Revision context changed. Review the Assembly Folder link first.");return f.Current;}
 private static string DocumentId(LibraryFolderLink link,string path)=>Hash(JsonSerializer.SerializeToUtf8Bytes(new[]{link.SourceKeyRaw,link.DrawingRevision,link.BomRevision,link.RootId,path.ToUpperInvariant()}));
 private async Task<SimLinkedFileRead> ReadDocumentFile(LibraryFolderLink link,string path)=>await Sources().ReadFile(new(link.Id,0,link.RootId,link.RelativePath,link.FolderName,"",link.AssemblyNumber,link.BomRevision,link.Actor.Name,link.Actor.AtUtc),path,"LIBRARY_DOCUMENT");
 internal async Task<object> Documents(string key,SimPersona p){Permission(p);Header(key);await gate.WaitAsync();try{var c=await FolderContext(key);var r=await ReadDocuments(key,c.Drawing,c.Bom);return new{record=r,token=DocumentsToken(r),canEdit=p.Can("assembly_library.edit")&&!PackageLocked(await Read(key)),documentOrigins=true,combinedDocumentUse=true};}finally{gate.Release();}}
 internal async Task<object> DocumentListing(string key,string folderToken,string relative,SimPersona p){Permission(p);Header(key);await gate.WaitAsync();try{
  var link=await DocumentLink(key,folderToken);relative=SimDrawingFolders.Normalize(relative);Require(relative.Equals(link.RelativePath,StringComparison.OrdinalIgnoreCase)||relative.StartsWith(link.RelativePath+"/",StringComparison.OrdinalIgnoreCase)||link.RelativePath.Length==0,"Stay within the linked assembly folder.");
  var listing=Sources().Browse(link.RootId,relative);var entries=new List<object>();foreach(var e in listing.Entries){DateTime? modified=null;long? size=null;if(!e.IsDirectory){var path=Path.Combine(Sources().Resolve(link.RootId,relative).Path,e.Name);var info=new FileInfo(path);if((info.Attributes&FileAttributes.ReparsePoint)!=0)continue;modified=info.LastWriteTimeUtc;size=info.Length;}entries.Add(new{e.Name,e.RelativePath,e.IsDirectory,modifiedUtc=modified,size});}return new{entries,listing.Truncated};
 }finally{gate.Release();}}
 internal async Task<object> DescribeDocument(string key,string folderToken,string path,SimPersona p){Permission(p);Header(key);await gate.WaitAsync();try{var link=await DocumentLink(key,folderToken);var read=await ReadDocumentFile(link,path);return new{read.Name,read.Source,id=DocumentId(link,path)};}finally{gate.Release();}}
 internal async Task<object> SaveDocument(LibraryDocumentCommand c,SimPersona p){Permission(p,write:true);Header(c.Key);await gate.WaitAsync();try{
  Require(!PackageLocked(await Read(c.Key)),"This package is fixed. Start changes or withdraw it from the assembly screen first.");var link=await DocumentLink(c.Key,c.FolderToken);var r=await ReadDocuments(c.Key,link.DrawingRevision,link.BomRevision);Require(DocumentsToken(r)==c.ExpectedToken,"Document selections changed. Reopen before saving.");
  Require(c.Purposes is not null&&c.Purposes.Length<=13&&c.Purposes.Distinct().Count()==c.Purposes.Length&&c.Purposes.All(x=>new[]{"DRAWING","BOM_SOURCE","WORK_INSTRUCTION","IMAGE","REFERENCE","OTHER","PART_EVIDENCE","TRAVELER","CHANGE_NOTES","QUOTE","NOTES","VPRO5_TXT","VPRO5_BMM_PDF"}.Contains(x)),"Choose supported document purposes.");
  Require(new[]{"UNIDENTIFIED","REFERENCE","MATERIALS","PRODUCTION","BOTH"}.Contains(c.Use),"Choose a document use.");Require(new[]{"UNKNOWN","ENGINEERING","PROTOTYPE","TESTING","USER_REPORTED_RELEASED"}.Contains(c.Status),"Choose a source document status.");
  Require(c.Number is not null&&c.Revision is not null&&c.Number.Length<=200&&c.Revision.Length<=100&&!c.Number.Any(char.IsControl)&&!c.Revision.Any(char.IsControl),"Document number or revision is too long or invalid.");
  Require(c.Origin is null or "UNIDENTIFIED" or "CUSTOMER_ORIGINAL" or "DLE_LEGACY" or "DLE_OS_CREATED","Choose a supported document origin.");
  var read=await ReadDocumentFile(link,c.RelativePath);Require(read.Source.SourceToken==c.SourceToken,"Source changed since selection. Reopen the file details; nothing saved.");var id=DocumentId(link,c.RelativePath);var previous=r.History.LastOrDefault(v=>v.Id==id);
  // Omission preserves the prior declaration for old clients. Reset must be explicit.
  var origin=c.Origin=="UNIDENTIFIED"?null:c.Origin??previous?.Origin;
  var evidence=c.Use is "PRODUCTION" or "BOTH"?read.Source.Sha256:null;
  if(previous is not null&&previous.Source.SourceToken==read.Source.SourceToken&&previous.Use==c.Use&&previous.Purposes.SequenceEqual(c.Purposes!)&&previous.Number==c.Number&&previous.Revision==c.Revision&&previous.Status==c.Status&&previous.Origin==origin)return new{record=r,token=DocumentsToken(r),canEdit=true,documentOrigins=true,combinedDocumentUse=true};
  if(evidence is not null){var dir=Path.Combine(root,"document-evidence");Directory.CreateDirectory(dir);var path=Path.Combine(dir,evidence);if(File.Exists(path))Require(Hash(await File.ReadAllBytesAsync(path))==evidence,"Saved evidence verification failed.");else{var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{await File.WriteAllBytesAsync(temp,read.Bytes);Require(Hash(await File.ReadAllBytesAsync(temp))==evidence,"Copy verification failed.");File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}}
  var version=new LibraryDocumentVersion(id,(previous?.Version??0)+1,link,read.Source,c.Purposes!,c.Use,c.Number!,c.Revision!,c.Status,evidence,Actor(p),origin);r=r with{Revision=r.Revision+1,History=[..r.History,version]};var target=DocumentsPath(c.Key,r.DrawingRevision,r.BomRevision);Directory.CreateDirectory(Path.GetDirectoryName(target)!);var pending=target+"."+Guid.NewGuid().ToString("N")+".tmp";
  try{await File.WriteAllTextAsync(pending,JsonSerializer.Serialize(r,Json));Require(DocumentsToken(JsonSerializer.Deserialize<LibraryDocumentsRecord>(await File.ReadAllTextAsync(pending),Json)!)==DocumentsToken(r),"Document save verification failed.");File.Move(pending,target,true);}finally{if(File.Exists(pending))File.Delete(pending);}
  return new{record=r,token=DocumentsToken(r),canEdit=true,documentOrigins=true,combinedDocumentUse=true};
 }finally{gate.Release();}}
 internal async Task<(byte[] Bytes,string Name)> DocumentEvidence(string key,string id,int version,SimPersona p){Permission(p);Header(key);await gate.WaitAsync();try{var c=await FolderContext(key);var r=await ReadDocuments(key,c.Drawing,c.Bom);var v=r.History.SingleOrDefault(x=>x.Id==id&&x.Version==version);Require(v?.EvidenceHash is not null,"This version has no saved production copy.");var bytes=await File.ReadAllBytesAsync(Path.Combine(root,"document-evidence",v!.EvidenceHash!));Require(Hash(bytes)==v.EvidenceHash,"Saved evidence verification failed.");return(bytes,Path.GetFileName(v.Source.RelativePath));}finally{gate.Release();}}
}
